WITH base AS (SELECT *, CASE WHEN country = 'JP' THEN 1 ELSE 0 END AS is_jp FROM suppliers WHERE LOWER(supplier_name) LIKE '%iam%') SELECT id, country, city, is_jp, COUNT(rating) OVER w_running AS running_count_rating, AVG(rating) OVER w_running AS running_avg_rating, MAX(rating) OVER w_running AS running_max_rating FROM base WHERE city != 'New York' WINDOW w_running AS (PARTITION BY country ORDER BY is_jp, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW);
